:root{--ink:#283c37;--paper:#fffdf4;--green:#466f58;--cream:#f6f1df}

*{box-sizing:border-box}

body{margin:0;background:var(--cream);color:var(--ink);font-family:ui-rounded,"Trebuchet MS",system-ui,sans-serif;overflow-x:hidden}

button{font:inherit;color:inherit;cursor:pointer;border:0}

button:focus-visible{outline:3px solid #e8a56a;outline-offset:3px}

.shell{max-width:1440px;margin:auto;padding:16px 25px 24px;min-height:100vh;display:flex;flex-direction:column}

.topbar{height:61px;display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}

.brand{display:flex;align-items:center;gap:11px;font-size:21px;font-weight:900;letter-spacing:-.7px}

.brand-mark{width:39px;height:39px;background:#dce89a;border:2px solid #365843;border-radius:14px;display:grid;place-items:center;font-size:23px;transform:rotate(-5deg);box-shadow:3px 3px #365843}

.brand small{display:block;color:#809083;font-size:10px;letter-spacing:1.6px;font-weight:800;margin-top:1px}

.top-right{display:flex;gap:9px;align-items:center}

.pill{padding:9px 13px;border:1.5px solid #dfe3ce;background:var(--paper);border-radius:99px;font-size:12px;font-weight:800;display:flex;align-items:center;gap:7px}

.berry{color:#99533e}

.icon-btn{width:40px;height:40px;border-radius:14px;background:var(--paper);border:1.5px solid #dfe3ce;font-size:18px}

.layout{flex:1;display:grid;grid-template-columns:minmax(0,1fr) 294px;gap:17px;min-height:0}

.world-card{position:relative;overflow:hidden;border:2px solid #344d3e;border-radius:25px;background:#b9dca7;box-shadow:0 12px 34px #2c49331c;min-height:500px;isolation:isolate}

.world-head{position:absolute;z-index:2;top:15px;left:16px;right:16px;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}

.location{background:#fffdf0ed;border:1.5px solid #344d3e;border-radius:16px;padding:9px 13px;box-shadow:3px 3px #344d3e26}

.location strong{font-size:14px;display:block}

.location span{font-size:10px;color:#718477;font-weight:700}

.weather{background:#fffdf0ed;border-radius:99px;padding:8px 11px;font-size:12px;font-weight:800}

.world-card canvas{width:100%;height:100%;position:absolute;inset:0;display:block;touch-action:none}

.world-hint{position:absolute;top:79px;left:50%;transform:translateX(-50%);white-space:nowrap;background:#294438d9;color:white;font-size:11px;font-weight:700;padding:8px 12px;border-radius:99px;pointer-events:none}

.nearby{position:absolute;left:15px;bottom:15px;background:#fffdf0ee;border:1.5px solid #344d3e;border-radius:15px;padding:9px 12px;display:flex;align-items:center;gap:9px;min-width:190px;box-shadow:2px 3px #344d3e23}

.nearby .face{font-size:25px}

.nearby b{font-size:12px;display:block}

.nearby small{font-size:10px;color:#7e8d7e}

.nearby .dot{margin-left:auto;width:9px;height:9px;background:#91c879;border-radius:50%}

.side{display:flex;flex-direction:column;gap:12px}

.card{background:var(--paper);border:1.5px solid #e4e2d2;border-radius:20px;padding:16px;box-shadow:0 5px 16px #455b3210}

.profile{display:flex;gap:11px;align-items:center}

.avatar{height:50px;width:50px;border-radius:17px;background:#f6d8b5;display:grid;place-items:center;font-size:28px;border:1.5px solid #384f3e}

.profile h2{margin:0 0 3px;font-size:16px}

.profile p{margin:0;color:#7d8c7d;font-size:11px}

.edit{margin-left:auto;background:#edf0df;border-radius:10px;padding:8px;font-size:12px}

.divider{height:1px;background:#ecebdd;margin:13px 0}

.stats{display:flex;justify-content:space-between;font-size:11px;color:#7c897b;font-weight:700}

.stats strong{color:var(--ink);font-size:12px}

.quest{background:#f3f5e8;border-radius:14px;padding:12px;margin-top:12px}

.quest-top{display:flex;justify-content:space-between;align-items:center}

.quest-top b{font-size:12px}

.quest-tag{font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.7px;background:#e1e9bd;color:#56714b;padding:5px 7px;border-radius:99px}

.quest p{font-size:11px;line-height:1.5;color:#788577;margin:7px 0 9px}

.progress{height:6px;border-radius:9px;background:#e0e5d6;overflow:hidden}

.progress i{display:block;height:100%;width:0;background:#7eaa71;border-radius:9px;transition:width .4s}

.progress-label{display:flex;justify-content:space-between;font-size:9px;color:#859081;margin-top:6px;font-weight:800}

.section-title{display:flex;align-items:center;justify-content:space-between;margin:0 0 10px}

.section-title b{font-size:13px}

.text-btn{background:none;color:#648060;font-weight:800;font-size:10px;padding:4px}

.friends-row{display:flex;gap:9px}

.friend-chip{flex:1;text-align:center;background:#f6f4e9;border-radius:13px;padding:9px 5px}

.friend-chip span{font-size:24px;display:block}

.friend-chip b{font-size:9px;display:block;margin-top:4px}

.empty-chip{color:#b4b9a6}

.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}

.action{background:#f5f4e9;border:1px solid #e6e5d6;border-radius:13px;padding:10px 8px;text-align:left;font-weight:800;font-size:11px;display:flex;align-items:center;gap:8px}

.action span{font-size:17px}

.action:hover,.icon-btn:hover,.edit:hover{background:#e8efd4}

.mobile-controls{display:none}

.footer{font-size:10px;color:#91a092;text-align:center;padding:11px 0 0}

.modal-backdrop{position:fixed;inset:0;background:#22392e8c;z-index:8;display:grid;place-items:center;padding:16px;backdrop-filter:blur(4px)}

.modal{width:min(440px,100%);background:var(--paper);border:2px solid #334d3c;border-radius:24px;padding:23px;box-shadow:0 18px 70px #1f382c55;animation:pop .2s ease-out}

.modal h2{margin:0;font-size:23px;letter-spacing:-.5px}

.modal .sub{color:#7a897b;font-size:12px;line-height:1.5;margin:6px 0 16px}

.close{float:right;background:#f0f0e5;border-radius:10px;font-size:16px;width:31px;height:31px}

.field-label{font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#738274;font-weight:900;display:block;margin:14px 0 7px}

.name-input{width:100%;border:1.5px solid #dfe3d2;border-radius:12px;padding:11px 12px;font:inherit;color:var(--ink);background:white;outline:none}

.choices{display:flex;gap:8px}

.choice{width:43px;height:43px;border-radius:13px;background:#f0efe2;border:2px solid transparent;font-size:23px}

.choice.selected{border-color:#547855;background:#eaf0d7}

.color-choice{width:34px;height:34px;border-radius:50%;border:2px solid white;box-shadow:0 0 0 1px #d8dccd;margin-right:5px}

.color-choice.selected{box-shadow:0 0 0 2px #436648}

.primary{width:100%;margin-top:19px;border-radius:13px;background:#476e55;color:white;padding:13px;font-weight:900;box-shadow:0 3px #34523f}

.primary:hover{background:#385d45}

.dialog-creature{display:flex;align-items:center;gap:13px;background:#f1f3e6;padding:12px;border-radius:16px;margin:12px 0}

.dialog-creature .big{font-size:44px}

.dialog-creature b{font-size:14px}

.dialog-creature small{display:block;color:#7c8b7b;font-size:11px;margin-top:3px}

.choice-actions{display:grid;gap:8px}

.choice-action{background:white;border:1.5px solid #e3e5d8;border-radius:13px;padding:12px;text-align:left;font-weight:800;font-size:12px}

.choice-action:hover{border-color:#95b285;background:#f5f8eb}

.toast{position:fixed;z-index:15;top:22px;left:50%;transform:translate(-50%,-20px);padding:11px 16px;border-radius:99px;background:#304b3b;color:white;font-size:12px;font-weight:800;box-shadow:0 7px 22px #1c332d30;opacity:0;transition:.25s;pointer-events:none}

.toast.show{opacity:1;transform:translate(-50%,0)}

.journal-list{display:grid;gap:8px;max-height:48vh;overflow:auto}

.journal-item{display:flex;align-items:center;gap:11px;background:#f3f3e8;padding:10px;border-radius:13px}

.journal-item .big{font-size:28px}

.journal-item b{font-size:12px}

.journal-item small{display:block;color:#82907f;font-size:10px;margin-top:3px}

.journal-item .status{margin-left:auto;color:#6e9a64;font-weight:900;font-size:10px}

.hidden{display:none!important}

@keyframes pop{from{transform:scale(.94);opacity:0}

to{transform:scale(1);opacity:1}

@media(max-width:850px){.shell{padding:10px 12px 14px}

.topbar{height:48px;margin-bottom:9px}

.brand{font-size:18px}

.brand-mark{width:34px;height:34px;font-size:20px}

.top-right{gap:6px}

.pill{padding:8px 10px;font-size:11px}

.icon-btn{width:36px;height:36px}

.layout{grid-template-columns:minmax(0,1fr) 250px;gap:10px}

.world-card{min-height:460px}

.card{padding:12px}

.side{gap:9px}

.quest{padding:10px;margin-top:9px}

@media(max-width:650px){body{overscroll-behavior:none}

.shell{height:100svh;min-height:560px;padding:7px 9px calc(7px + env(safe-area-inset-bottom))}

.topbar{height:42px;margin-bottom:7px}

.brand{font-size:16px;gap:8px}

.brand-mark{width:31px;height:31px;border-radius:11px;font-size:18px}

.brand small{font-size:8px}

.pill{font-size:10px;padding:7px 9px}

.icon-btn{width:33px;height:33px}

.layout{display:flex;flex-direction:column;gap:7px;min-height:0}

.world-card{flex:1;min-height:0;border-radius:20px}

.world-head{top:10px;left:10px;right:10px}

.location{padding:7px 10px;border-radius:12px}

.location strong{font-size:12px}

.location span{font-size:9px}

.weather{padding:7px 9px;font-size:10px}

.world-hint{top:65px;font-size:9px;padding:7px 10px}

.nearby{left:9px;bottom:9px;min-width:150px;padding:7px 9px;border-radius:12px}

.nearby .face{font-size:21px}

.nearby b{font-size:10px}

.nearby small{font-size:9px}

.side{display:grid;grid-template-columns:1fr 1fr;gap:7px;flex:none}

.side .card{padding:9px;border-radius:15px}

.profile-card{grid-column:1/2}

.buddy-card{grid-column:2/3}

.profile{gap:7px}

.avatar{width:37px;height:37px;border-radius:12px;font-size:22px}

.profile h2{font-size:12px}

.profile p{font-size:9px}

.edit{padding:6px;font-size:10px}

.divider{margin:8px 0}

.stats{font-size:9px}

.stats strong{font-size:10px}

.quest{padding:8px;margin-top:8px;border-radius:10px}

.quest-top b{font-size:10px}

.quest-tag{font-size:8px;padding:4px 5px}

.quest p{font-size:9px;margin:5px 0 6px;line-height:1.35}

.progress-label{font-size:8px;margin-top:4px}

.section-title{margin-bottom:5px}

.section-title b{font-size:11px}

.text-btn{font-size:9px}

.friends-row{gap:5px}

.friend-chip{padding:6px 3px;border-radius:9px}

.friend-chip span{font-size:20px}

.friend-chip b{font-size:8px;margin-top:2px}

.action{font-size:9px;padding:7px 5px;gap:4px;border-radius:9px}

.action span{font-size:14px}

.footer{display:none}

.mobile-controls{display:flex;position:absolute;z-index:3;left:10px;right:10px;bottom:63px;justify-content:space-between;align-items:end;pointer-events:none}

.dpad{width:96px;height:86px;position:relative;pointer-events:auto}

.dpad button{position:absolute;width:34px;height:32px;border-radius:10px;background:#fffdf0dc;border:1.5px solid #354d3d;font-size:14px;box-shadow:0 2px #354d3d40;touch-action:none}

.dpad .up{left:31px;top:0}

.dpad .down{left:31px;bottom:0}

.dpad .left{left:0;top:27px}

.dpad .right{right:0;top:27px}

.act-btn{pointer-events:auto;background:#f2a17e;color:#412f2a;border:2px solid #3c4d3e;border-radius:18px;padding:13px 16px;font-weight:900;font-size:12px;box-shadow:0 3px #344b3b;touch-action:manipulation}

.act-btn:active,.dpad button:active{transform:translateY(2px);box-shadow:none}

.world-hint{max-width:90vw;overflow:hidden}

.modal{padding:19px;border-radius:20px}

