 <main class="layout"><section class="world-card" id="worldCard"><canvas id="game" aria-label="Wildwhim meadow game"></canvas><div class="world-head"><div class="location"><strong>✨ Dappledell Meadow</strong><span>Whispering Woods · Spring</span></div><div class="weather">☀️ &nbsp;Breezy</div></div><div class="world-hint" id="hint">Tap the meadow to wander · meet a magical friend ✨</div><div class="nearby" id="nearby"><span class="face">🌿</span><div><b>Someone's nearby</b><small>Explore to say hello</small></div><span class="dot"></span></div><div class="mobile-controls"><div class="dpad"><button class="up" data-dir="up" aria-label="Move up">▲</button><button class="down" data-dir="down" aria-label="Move down">▼</button><button class="left" data-dir="left" aria-label="Move left">◀</button><button class="right" data-dir="right" aria-label="Move right">▶</button></div><button class="act-btn" id="touchAct">♡ &nbsp;TALK</button></div></section>
 <aside class="side"><section class="card profile-card"><div class="profile"><div class="avatar" id="avatar">🧙🏻‍🌾</div><div><h2 id="playerName">Little Wanderer</h2><p>Wizard Farmer · Lv. 1</p></div><button class="edit" id="customize" aria-label="Customize farmer">✎</button></div><div class="divider"></div><div class="stats"><span>🌱 Meadow steps</span><strong id="steps">0</strong></div><div class="quest"><div class="quest-top"><b>🌙 A gentle hello</b><span class="quest-tag">FIRST FRIEND</span></div><p>Find Moonmoss, the shy moon-lamb, and share a little magic.</p><div class="progress"><i id="questProgress"></i></div><div class="progress-label"><span id="questText">Make a new friend</span><span id="questNum">0 / 1</span></div></div></section>
 <section class="card buddy-card"><div class="section-title"><b>♡ &nbsp;Your kindred</b><button class="text-btn" id="openJournal">Field notes →</button></div><div class="friends-row" id="friendsRow"></div></section><section class="card toolbox"><div class="section-title"><b>🌼 &nbsp;Wizard satchel</b><span style="font-size:9px;color:#879281">little things, big magic</span></div><div class="actions"><button class="action" id="gather"><span>🫐</span>Gather berries</button><button class="action" id="sing"><span>✨</span>Cast a kind spell</button><button class="action" id="journalAction"><span>📖</span>Field notes</button><button class="action" id="look"><span>👀</span>Take it in</button></div></section></aside></main><footer class="footer">A cozy little world for wandering · Tap anywhere in the meadow to walk there</footer></div><div id="modalRoot"></div><div class="toast" id="toast" role="status" aria-live="polite"></div>
 <script>
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),SAVE='wildwhim-save-v1';
+const base={name:'Little Wanderer',hair:'🧙🏻‍🌾',coat:'#e68f71',berries:3,steps:0,friends:[],met:[],bond:{},gifts:[],started:false};
+let raw={};try{raw=JSON.parse(localStorage.getItem(SAVE)||'{}')||{}}catch{};let save={...base,...raw,bond:{...base.bond,...(raw.bond||{})},friends:Array.isArray(raw.friends)?raw.friends:[],met:Array.isArray(raw.met)?raw.met:[],gifts:Array.isArray(raw.gifts)?raw.gifts:[]};
+const species=[
+{id:'moonmoss',name:'Moonmoss',kind:'Lunar lamb',emoji:'🌙',x:595,y:365,color:'#dbe7be',accent:'#e9cf79',blurb:'A serious little moon-lamb with a clover crown. Collects lost wishes and polished stones.',voice:['The moon keeps careful records. Your kindness is written among the stars.','I found this moon-pearl while gathering dew. It belongs with you.','Even the night feels warm when we sit together.'],gift:'Moon-pearl',buff:'Moonlight: your steps sparkle and you move a little quicker.'},
+{id:'puddlewing',name:'Puddlewing',kind:'Raincloud duckling',emoji:'🐣',x:780,y:460,color:'#f2d86c',accent:'#a6d9df',blurb:'A giggly cloud-duck who makes tiny rainbows and hoards shiny buttons.',voice:['Quack! That spell made my feathers fizz!','I fished a sky-button from the pond for you. It is extremely important.','Ready, wizard? Let us splash a rainbow all the way to Tuesday!'],gift:'Sky-button',buff:'Cloud hop: your happy buddy brings you extra berries.'},
+{id:'bramblekit',name:'Bramblekit',kind:'Thorn-tailed fox',emoji:'🦊',x:278,y:280,color:'#d98155',accent:'#87ae70',blurb:'A cool fox with a rosebud tail. Pretends to be aloof; secretly loves flower crowns.',voice:['You have decent taste in spells. I approve.','Found a heart-berry in the brambles. Do not make it weird.','Race you to the old oak! Winner gets bragging rights.'],gift:'Heart-berry',buff:'Bramble luck: berry patches give you an extra berry.'},
+{id:'cinderpup',name:'Cinderpup',kind:'Ashen fox-drake',emoji:'🐉',x:175,y:455,color:'#64707b',accent:'#ea986a',blurb:'A solemn fox-drake fusion guarding an ancient ember. It takes promises very seriously.',voice:['Magic is a promise. Keep yours, and I will keep the fire lit.','A warm ember-stone. It remembers every brave thing you have done.','The old flame approves of you. That is not praise I give lightly.'],gift:'Ember-stone',buff:'Ember ward: a steady little fire keeps your magic bright.'},
+{id:'mirthmoth',name:'Mirthmoth',kind:'Moth-cat fusion',emoji:'🦋',x:865,y:290,color:'#bd9cdb',accent:'#f2bdd0',blurb:'A fluffy cat-moth with velvet wings, a silly grin, and a fondness for moonlit games.',voice:['Prrrr-bzzzt! Your hat is magnificent, tiny wizard!','I made you a soft glow-flower. It purrs if you ask nicely.','Tag! You are the keeper of the moonbeam now!'],gift:'Glow-flower',buff:'Moth cuddle: friends share a cozy little speed boost.'}
+];
+let player={x:390,y:470,walk:0},keys={},touchDirs={},target=null,lastTime=0,time=0,toastTimer,dialogueTarget=null,nearbyCreature=null;
+const saveIt=()=>{try{localStorage.setItem(SAVE,JSON.stringify(save))}catch{}renderUI()};
+function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(r.width*d));canvas.height=Math.max(1,Math.round(r.height*d));ctx.imageSmoothingEnabled=false}new ResizeObserver(resize).observe(canvas);resize();
+function box(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
+function pixelScene(dt){time+=dt;ctx.setTransform(canvas.width/500,0,0,canvas.height/350,0,0);ctx.clearRect(0,0,500,350);
+// dappled pixel meadow, distant hills, tiled paths
+box(0,0,500,350,'#add5bd');box(0,0,500,115,'#b9d9cf');box(0,98,500,80,'#8ebc8d');box(0,125,500,95,'#a5cb91');box(0,185,500,165,'#aacf83');
+// chunky cloudlets and sun
+box(405,36,32,28,'#f8eab0');box(411,31,20,7,'#fff2be');box(412,43,20,12,'#fff2be');
+for(const [x,y,w] of [[85,48,48],[240,72,35],[350,58,25]]){box(x,y,w,7,'#f4f3dc');box(x+7,y-5,w-14,6,'#f4f3dc');box(x+4,y+7,w-9,4,'#e3ead3')}
+// cottage
+box(27,121,68,45,'#ead9aa');box(21,113,80,12,'#a9644f');box(32,105,58,11,'#bd7657');box(36,137,15,29,'#89644d');box(63,132,19,15,'#a8d7ce');box(68,137,3,10,'#f5d880');
+// orchard trees with blocky layered canopies
+for(const [x,y,c] of [[22,178,'#527c5c'],[116,160,'#698e61'],[459,177,'#587d56'],[396,157,'#6e9664']]){box(x-4,y,9,24,'#866348');box(x-18,y-20,37,22,c);box(x-12,y-29,27,15,c);box(x-24,y-12,13,16,c);box(x+11,y-13,14,17,c);box(x-4,y-24,5,4,'#c7d994')}
+// stepping-stone path winding through the field
+for(let i=0;i<18;i++){let x=i*34-12,y=260+Math.sin(i*.65)*24;box(x,y,18,8,'#d7c89d');box(x+3,y+1,12,2,'#e9dbb5')}
+// pond, reeds, flowers and checker patches
+box(365,225,93,30,'#69b7b2');box(372,219,75,8,'#80cbc2');box(380,230,18,3,'#d9f0d7');box(447,216,3,20,'#547c51');box(451,220,4,19,'#688e54');
+for(let i=0;i<76;i++){let x=(i*67+23)%500,y=147+(i*43)%195;if((x>155&&x<350&&y>225&&y<300)||(x>360&&y>215&&y<260))continue;box(x,y,2,5,i%4===0?'#f1e7a5':i%3===0?'#79aa68':'#80b174');if(i%7===0){box(x-2,y-2,3,3,'#f2c8a0');box(x+2,y-2,3,3,'#f2c8a0')}}
+// little spell motes
+for(let i=0;i<10;i++){let x=(i*71+time*15)%500,y=130+(i*47)%180;box(x,y,2,2,'#fff4be');if(i%3===0)box(x+3,y-3,2,2,'#fff4be')}
+for(const c of species)drawCreature(c);
+drawFarmer();ctx.setTransform(1,0,0,1,0,0)}

