window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key]=true;if(e.key===' '||e.key==='Enter')hello()});window.addEventListener('keyup',e=>keys[e.key]=false);document.querySelectorAll('.dpad button').forEach(b=>{let d=b.dataset.dir,on=e=>{e.preventDefault();touchDirs[d]=true},off=e=>{e.preventDefault();touchDirs[d]=false};b.addEventListener('pointerdown',on);b.addEventListener('pointerup',off);b.addEventListener('pointerleave',off);b.addEventListener('pointercancel',off)});document.getElementById('touchAct').onclick=hello;
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function showToast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
function renderNearby(){const boxEl=document.getElementById('nearby');if(!nearbyCreature){boxEl.innerHTML='<span class="face">🌿</span><div><b>Someone’s nearby</b><small>Explore to say hello</small></div><span class="dot"></span>';return}let c=nearbyCreature,level=save.friends.includes(c.id)?(save.bond[c.id]||1):0;boxEl.innerHTML=`<span class="face">${c.emoji}</span><div><b>${esc(c.name)} ${level?`· Bond ${level}`:'· Nearby'}</b><small>${level?'Your kindred':'Tap TALK to introduce yourself'}</small></div><span class="dot"></span>`}
function renderUI(){document.getElementById('berryCount').textContent=save.berries;document.getElementById('playerName').textContent=save.name;document.getElementById('avatar').textContent=save.hair;document.getElementById('steps').textContent=Math.floor(save.steps);let row=document.getElementById('friendsRow');row.innerHTML=species.map(c=>{let friend=save.friends.includes(c.id);return `<div class="friend-chip ${friend?'':'empty-chip'}" title="${esc(c.name)}"><span>${friend?c.emoji:'?'}</span><b>${friend?esc(c.name):'???'}</b></div>`}).join('');let done=save.friends.includes('moonmoss');document.getElementById('questProgress').style.width=done?'100%':'0%';document.getElementById('questText').textContent=done?'Moonmoss is your friend!':'Make a new friend';document.getElementById('questNum').textContent=done?'1 / 1':'0 / 1';renderNearby()}
function openModal(html){const root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop" role="presentation"><section class="modal" role="dialog" aria-modal="true">${html}</section></div>`;root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal()});root.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal)}
function closeModal(){document.getElementById('modalRoot').innerHTML='';dialogueTarget=null}
function nearestCreature(){return species.filter(c=>Math.hypot(c.x-player.x,c.y-player.y)<135).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0]}
function hello(){let c=nearestCreature();if(c)openMeet(c);else showToast('Wander close to a creature first ✨')}
function openMeet(c){dialogueTarget=c;let bond=save.bond[c.id]||0,friend=save.friends.includes(c.id),voice=c.voice[(bond+save.met.filter(id=>id===c.id).length)%c.voice.length];let title=friend?`A little visit with ${c.name}`:`A magical hello`;
openModal(`<button class="close" data-close aria-label="Close">×</button><h2>${title}</h2><p class="sub">Your wizard-farmer magic turns a kind thought into words.</p><div class="dialog-creature"><span class="big">${c.emoji}</span><div><b>${esc(c.name)} <span style="color:#88927e;font-weight:600">· ${esc(c.kind)}</span></b><small>${esc(c.blurb)}</small></div></div><p style="font-size:13px;line-height:1.55;margin:10px 1px 5px"><b>${esc(c.name)} says:</b> “${esc(voice)}”</p><p class="bond">${friend?`♡ Bond ${bond} · ${bond>=6?'Best buddies':bond>=3?'Close friends':'Getting acquainted'}`:'♡ A new friendship is waiting'}</p><div class="choice-actions"><button class="choice-action" data-kind="talk">💬 &nbsp; Listen and answer kindly<small>Share a gentle conversation and grow closer.</small></button><button class="choice-action" data-kind="play">🎲 &nbsp; Play a little game<small>Make them laugh; kindness is its own magic.</small></button>${save.berries>0?`<button class="choice-action" data-kind="gift">🫐 &nbsp; Offer a berry <small>You have ${save.berries} ${save.berries===1?'berry':'berries'} to share.</small></button>`:''}<button class="choice-action" data-kind="spell">✨ &nbsp; Cast a tiny friendship spell<small>Warm sparkles, no tricks—just a little encouragement.</small></button></div>`);
rootChoiceHandlers(c)}
function rootChoiceHandlers(c){document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>bondAction(c,b.dataset.kind))}
const moments={moonmoss:{talk:'You ask what the stars have been whispering. Moonmoss answers in a careful, thoughtful voice.',play:'You play cloud-shapes: Moonmoss wins by identifying a constellation in a puddle.',gift:'Moonmoss accepts your berry with a solemn nod, then tucks it away for later.',spell:'A warm silver glow settles around Moonmoss. For once, the little lamb smiles.'},puddlewing:{talk:'You ask about the pond. Puddlewing tells a long, wobbly story involving three ducks and a hat.',play:'You splash at the pond. Puddlewing makes a rainbow and declares you both champions.',gift:'Puddlewing takes the berry, does a happy wiggle, and quacks a thank-you.',spell:'Your kind spell makes Puddlewing’s fluffy cloud-feathers fizz with tiny stars.'},bramblekit:{talk:'You compliment the rosebud tail. Bramblekit pretends not to care, but sits closer.',play:'You race to the old oak. Bramblekit lets you win by exactly one whisker.',gift:'Bramblekit takes the berry. “A fair trade,” they say, and quietly saves half for you.',spell:'A few rose-petals whirl around Bramblekit. They call it “acceptable.”'},cinderpup:{talk:'You ask about the old ember. Cinderpup shares a serious story about keeping promises.',play:'You play a quiet guessing game with ember-shadows. Cinderpup’s grin is almost visible.',gift:'Cinderpup accepts your offering with a respectful bow and guards it carefully.',spell:'Your magic steadies the ancient flame. Cinderpup trusts you with its warmth.'},mirthmoth:{talk:'You ask about the velvet wings. Mirthmoth replies with a purr, a buzz, and a very silly joke.',play:'You play moonbeam tag. Mirthmoth wins, then gives you a victory sticker anyway.',gift:'Mirthmoth hugs the berry, purrs loudly, and gives you a soft wing-bump.',spell:'Your sparkles make Mirthmoth spin until both of you are giggling.'}};
function bondAction(c,kind){let wasFriend=save.friends.includes(c.id),prior=save.bond[c.id]||0;if(kind==='gift'&&save.berries<=0){closeModal();showToast('No berries to share just now. Gather some first!');return}if(kind==='gift')save.berries--;
if(!save.met.includes(c.id))save.met.push(c.id);if(!wasFriend)save.friends.push(c.id);let gain=kind==='spell'&&save.friends.includes('cinderpup')&&c.id!=='cinderpup'?2:1;save.bond[c.id]=prior+gain;
let message=moments[c.id][kind];let giftsNow=[];for(const threshold of [3,6]){let key=`${c.id}:${threshold}`;if(save.bond[c.id]>=threshold&&!save.gifts.includes(key)){save.gifts.push(key);giftsNow.push(threshold)}}
if(kind==='play'&&c.id==='puddlewing'){save.berries+=1;message+=' Puddlewing finds a berry in the grass for you!'}if(kind==='talk'&&c.id==='moonmoss'){save.steps+=2;message+=' Moonmoss teaches you a star-step.'}
save.started=true;saveIt();let giftNotice=giftsNow.length?`<div class="gift">🎁 <b>${esc(c.name)} gave you a ${esc(c.gift)}!</b><br>${esc(c.name)} made or found it just for you. ${giftsNow.length>1?'Your bond is shining brighter than ever.':''}</div>`:'';if(giftsNow.length)message+=` ${c.voice[1]}`;
let actionLabel={talk:'You listened and answered kindly.',play:'You played together.',gift:'You shared a berry.',spell:'You cast a friendship spell.'}[kind];openModal(`<button class="close" data-close aria-label="Close">×</button><h2>${wasFriend?'A moment together':'A new friend!'}</h2><p class="sub">${actionLabel} ${gain>1?'Cinderpup’s ember magic gives your kind spell extra warmth.':''}</p><div class="dialog-creature"><span class="big">${c.emoji}</span><div><b>${esc(c.name)} · Bond ${save.bond[c.id]}</b><small>${esc(c.buff)}</small></div></div><p style="font-size:13px;line-height:1.55">${esc(message)}</p>${giftNotice}<button class="primary" id="visitAgain">Stay a little longer</button><button class="primary" data-close style="background:#e8eddb;color:#334b39;box-shadow:none">Back to the meadow</button>`);document.getElementById('visitAgain').onclick=()=>openMeet(c);showToast(giftsNow.length?`${c.name} gave you a ${c.gift}!`:wasFriend?`${c.name} feels a little closer ♡`:`${c.name} is your new friend!`)}

