const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const assert = require('node:assert/strict');

(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('file:///home/runner/work/PlayGround/PlayGround/index.html');
  await page.waitForTimeout(600);
  assert.equal(await page.title(), 'Wildwhim — A little world of wonder');
  assert.equal(await page.locator('#berryCount').innerText(), '3');
  assert.equal(await page.locator('.friend-chip').count(), 5);
  const canvas = page.locator('#game');
  const box = await canvas.boundingBox();
  await page.mouse.click(box.x + box.width * 0.595, box.y + box.height * 0.522);
  await page.waitForTimeout(1600);
  await page.locator('#touchAct').click();
  await page.locator('[data-kind="talk"]').click();
  assert.match(await page.locator('.modal').innerText(), /A new friend!/);
  assert.match(await page.locator('.modal').innerText(), /Moonmoss · Bond 1/);
  await page.locator('[data-close]').last().click();
  assert.match(await page.locator('#nearby').innerText(), /Moonmoss/);
  const stored = JSON.parse(await page.evaluate(() => localStorage.getItem('wildwhim-save-v1')));
  assert.deepEqual(stored.friends, ['moonmoss']);
  assert.equal(stored.bond.moonmoss, 1);
  await page.reload();
  await page.waitForTimeout(250);
  assert.equal((await page.locator('.friend-chip').first().innerText()).includes('Moonmoss'), true);
  await page.locator('#openJournal').click();
  assert.match(await page.locator('.modal').innerText(), /Friendship boost/);
  await page.locator('[data-close]').click();
  await page.locator('#customize').click();
  await page.locator('#nameInput').fill('Test Wizard');
  await page.locator('[data-coat="#7098c5"]').click();
  await page.locator('#saveFarmer').click();
  assert.equal(await page.locator('#playerName').innerText(), 'Test Wizard');
  const desktop = await page.evaluate(() => ({
    viewport: [innerWidth, innerHeight],
    document: [document.documentElement.scrollWidth, document.documentElement.scrollHeight],
    shell: document.querySelector('.shell').getBoundingClientRect().toJSON(),
    canvas: document.querySelector('#game').getBoundingClientRect().toJSON()
  }));
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/wildwhim-desktop.jpg', type: 'jpeg', quality: 72 });
  await page.setViewportSize({ width: 390, height: 844 });
  await page.waitForTimeout(350);
  const mobile = await page.evaluate(() => ({
    viewport: [innerWidth, innerHeight],
    document: [document.documentElement.scrollWidth, document.documentElement.scrollHeight],
    shell: document.querySelector('.shell').getBoundingClientRect().toJSON(),
    world: document.querySelector('.world-card').getBoundingClientRect().toJSON(),
    controls: getComputedStyle(document.querySelector('.mobile-controls')).display,
    dpad: document.querySelector('.dpad').getBoundingClientRect().toJSON()
  }));
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/wildwhim-mobile.jpg', type: 'jpeg', quality: 72 });
  assert.equal(mobile.document[0], mobile.viewport[0]);
  assert.equal(mobile.document[1], mobile.viewport[1]);
  assert.notEqual(mobile.controls, 'none');
  await page.locator('#gather').click();
  assert.equal(await page.locator('#berryCount').innerText(), '4');
  if (errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`);
  console.log(JSON.stringify({ desktop, mobile, save: stored, errors }, null, 2));
  await browser.close();
})().catch(err => { console.error(err); process.exit(1); });

